    "answer": "Приложение формирует HTTP-данные, при HTTPS TLS защищает их, транспорт передаёт поток через TCP (для HTTP/3 используется QUIC поверх UDP), IP обеспечивает адресацию и маршрутизацию, канальный уровень доставляет кадры по локальному сегменту. На маршрутизаторе канальные заголовки меняются; IP-адреса обычно сохраняются, кроме NAT и туннелей.",
