    "answer": "Префикс /26 оставляет 6 бит для адресов, всего 64 адреса. Диапазон 10.20.30.64–127, обычный network .64, broadcast .127, 62 адреса хостов .65–126. Для /31 point-to-point и /32 действуют специальные правила. Облачная платформа может резервировать дополнительные адреса.",
