    "answer": "Маршрут определяет next hop. Для назначения вне локального сегмента Ethernet-кадр адресуется MAC следующего шлюза, при этом IP назначения остаётся удалённым адресом. ARP разрешает IPv4 адрес next hop в MAC на локальном сегменте. Каждый L3 hop строит новый канальный кадр.",
