    "question": "Чем IPv6 Neighbor Discovery отличается от ARP?",
    "answer": "IPv6 ND использует ICMPv6 и включает обнаружение соседей, маршрутизаторов, проверку достижимости и duplicate address detection. Neighbor Solicitation/Advertisement обычно используют multicast или unicast, а не IPv4 broadcast ARP. Блокировка ICMPv6 целиком ломает важные функции IPv6, включая обнаружение MTU пути.",
