    "question": "Чем access-порт VLAN отличается от trunk и где появляется тег 802.1Q?",
    "answer": "VLAN разделяет L2 broadcast domains. Access-порт обычно связан с одной VLAN и принимает/отправляет нетегированные кадры для конечного устройства; trunk переносит несколько VLAN с тегами 802.1Q, с возможным исключением native VLAN по конфигурации. Для обмена между VLAN требуется L3 маршрутизация.",
