    "answer": "ECMP позволяет использовать несколько маршрутов одинаковой стоимости. Выбор next hop обычно основан на хеше полей потока, зависящем от реализации; разные соединения могут идти через разные пути, один из которых деградировал. Per-flow hashing уменьшает reordering по сравнению с per-packet распределением. Проверять надо конкретные flow и состояние next hops.",
