    "answer": "OSPF — link-state IGP для маршрутизации внутри административного домена, вычисляющий пути по топологии и стоимости. BGP обменивается достижимостью префиксов и атрибутами, позволяя применять policy между автономными системами и внутри них. BGP не выбирает маршрут только по минимальному RTT. В дата-центре выбор зависит от fabric и модели управления.",
