    "question": "Как работает TCP three-way handshake и что подтверждают SYN, SYN-ACK и ACK?",
    "answer": "Клиент отправляет SYN с начальным sequence number, сервер отвечает SYN-ACK с подтверждением и своим sequence number, клиент подтверждает ответ ACK. Устанавливаются начальные параметры и состояние соединения на обеих сторонах. Успех handshake доказывает доступность TCP на этом пути, но не готовность TLS, HTTP или базы данных.",
