    "question": "Чем TCP flow control отличается от congestion control?",
    "answer": "Flow control защищает получателя от переполнения его буфера через advertised receive window. Congestion control регулирует объём данных в полёте с учётом состояния сети и алгоритма отправителя. Эффективная передача ограничена обоими механизмами, а также приложением и RTT. Zero window может указывать на медленного потребителя, retransmissions не обязательно на недостаток receive buffer.",
    "follow_up": "Что такое rwnd и cwnd? Как отличить zero window от потерь?",
