    "answer": "Для заполнения канала нужен bandwidth-delay product: 1e9 бит/с × 0,1 с / 8 = 12,5 MB данных в полёте. Если эффективное окно меньше, максимальная скорость примерно window/RTT при прочих равных. Window scaling, буферы, cwnd, loss и приложение влияют на реальный результат; BDP — ориентир, а не обещание throughput.",
