    "answer": "ClientHello и ServerHello согласуют параметры и ключевой обмен; типичный full handshake использует ephemeral key agreement. Сервер подтверждает свою идентичность сертификатом и подписью CertificateVerify; Finished проверяет целостность handshake. После установления ключей application data защищены AEAD. PSK resumption имеет отличия, а клиентский сертификат нужен только при соответствующей конфигурации.",
