    "answer": "Проверка включает доверенную цепочку, срок действия, назначение ключа и совпадение identity сервиса с именем, которое проверяет клиент. Наличие доверенного CA не означает, что сертификат выдан нужному hostname. Для современных DNS identities используют SAN; IP identity требует соответствующего IP SAN. Ошибка времени, отсутствующий intermediate или несовместимые параметры тоже возможны.",
