    "answer": "SNI передаёт имя сервера в TLS ClientHello, чтобы endpoint выбрал подходящую конфигурацию сертификата. HTTP Host или :authority относится к HTTP маршрутизации и поступает после установления обычного HTTPS соединения. При запросе по IP может не передаваться подходящее SNI, поэтому выбирается default virtual host. Проверять нужно оба уровня и имя сертификата.",
