    "answer": "При mutual TLS обе стороны подтверждают identity сертификатами согласно политике trust. Нужно независимо настраивать доверие и authorization для клиентов, выпускать ограниченные по сроку credentials, иметь период перекрытия при ротации CA и сертификатов и проверять reload/новые соединения. Уже установленные соединения могут не проходить новый handshake до переподключения.",
