    "question": "Чем TLS termination отличается от TLS passthrough и повторного шифрования до backend?",
    "answer": "При termination proxy завершает TLS и получает HTTP или иной plaintext протокол. При passthrough TLS-сессия устанавливается между клиентом и backend, а proxy пересылает транспортные данные; маршрутизация может использовать доступные метаданные ClientHello. Re-encryption создаёт отдельную TLS-сессию proxy→backend, требующую собственной проверки identity и trust. Выбор влияет на observability, безопасность и L7 функции.",
