    "question": "Чем INPUT, OUTPUT и FORWARD отличаются при фильтрации трафика Linux?",
    "answer": "INPUT относится к пакетам для локальной системы, OUTPUT — к локально создаваемым пакетам, FORWARD — к маршрутизируемому через хост трафику. В nftables цепочка получает соответствующий hook и priority; имя цепочки само по себе ничего не определяет. Контейнерные и NAT сценарии требуют учёта реального пути пакета.",
