    "answer": "Stateless фильтрует пакеты по их собственным признакам. Stateful использует состояние потока, например ct state established,related, чтобы учитывать пакеты ответного направления и связанные соединения. Conntrack ведёт таблицу flow и timeout, которая не совпадает с TCP-состоянием приложения. При переполнении возможны сбои новых потоков.",
