    "answer": "SNAT изменяет source адрес или порт, например при выходе приватной сети наружу. DNAT изменяет destination, например при публикации внутреннего сервиса. Masquerade — разновидность SNAT, использующая адрес исходящего интерфейса, удобная при динамическом IP. Stateful NAT обычно хранит mapping в conntrack и применяет обратное преобразование к ответам.",
