    "answer": "Проверить адреса, policy rules и маршрут с фактическим source через ip route get DEST from SOURCE. Затем сопоставить результат с capture на предполагаемом интерфейсе и обратном пути. Bind приложения, network namespace, fwmark и NAT способны изменить наблюдаемое поведение. Проверка маршрута — модель решения ядра, packet capture подтверждает фактическое событие.",
