    "question": "На Windows не работает WinRM HTTPS 5986 с Linux, но RDP доступен. Как локализовать отказ?",
    "answer": "Доступность RDP доказывает только работу соответствующего пути и порта. Проверить DNS/IP, source и маршруты Linux, TCP handshake на 5986, capture на обеих сторонах, Windows listener и scoped firewall rules. После успешного TCP отдельно проверить TLS trust/hostname и WinRM authentication/configuration. Если SYN не приходит на Windows, исследовать маршрут и фильтрацию до хоста; если приходит без ответа, проверить локальный стек и обратный путь.",
