    "question": "Как передать сетевому инженеру доказательства инцидента, чтобы не получить ответ «проблема на хосте»?",
    "answer": "Зафиксировать точный интервал с timezone, source/destination IP и ports, протокол, выбранные интерфейсы, маршрут, результат socket/listener и приложенческие ошибки. Согласовать ограниченный capture на обоих концах и сравнить наличие SYN/ответа либо валидных UDP datagrams. Проверить локальные firewall counters и обратный путь. Передать наблюдаемые факты отдельно от гипотезы, согласовать следующую точку capture и критерий восстановления.",
