    "question": "Что такое Terraform и чем его декларативная модель отличается от Bash-скрипта?",
    "answer": "Terraform описывает желаемую инфраструктуру ресурсами HCL. Core строит граф зависимостей, сопоставляет конфигурацию с state и наблюдаемыми объектами, затем через providers выполняет согласованные изменения. Bash обычно описывает последовательность команд; идемпотентность приходится проектировать самостоятельно. Terraform не является постоянно работающим reconciler.",
    "follow_up": "Почему повторный apply обычно не создаёт дубликаты? Когда второй plan всё же покажет изменения?",
