    "answer": "Init инициализирует backend, устанавливает необходимые child modules и provider plugins, создаёт или обновляет dependency lock file. В .terraform находятся рабочие данные и установленные зависимости; .terraform.lock.hcl фиксирует выбранные providers и checksums. Init сам по себе не создаёт описанные managed resources. Повторный init нужен при изменении backend или зависимостей.",
