    "answer": "Без файла apply сначала строит новый plan и обычно запрашивает подтверждение. С переданным plan-файлом Terraform выполняет сохранённые действия без дополнительного запроса подтверждения; состояние может стать несовместимым и применение будет отклонено. Plan-файл содержит конфигурацию и потенциально чувствительные данные, поэтому его нужно защищать и связывать с конкретным commit.",
