    "question": "Как диагностировать Cycle error в Terraform и не скрывать её ручным порядком apply?",
    "answer": "Цикл означает, что граф зависимостей невозможно упорядочить. Найти взаимные references, module-level depends_on или комбинацию replacement и lifecycle, которая создаёт замкнутый путь. Разделить вычисляемые входы, ресурсы и стадии владения; убрать ненужные зависимости или изменить архитектуру. Повторный запуск с той же конфигурацией не исправит цикл.",
