    "practice": "На синтетических terraform_data воспроизвести взаимные ссылки, исправить одну и повторить validate/plan.",
    "rubric": "Найти логическую причину цикла; не путать dependency graph с текстовым порядком.",
    "source": "https://developer.hashicorp.com/terraform/cli/commands/graph"
