    "answer": "required_version ограничивает версии Terraform CLI. required_providers объявляет адрес и допустимые версии plugins. Provider block настраивает конкретный экземпляр provider, например endpoint и identity. Один provider может иметь несколько конфигураций с alias; выбор установленной версии фиксируется lock file, а не произвольным alias.",
