    "question": "Что фиксирует .terraform.lock.hcl и почему он не фиксирует версии child modules?",
    "answer": "Lock file записывает выбранные provider versions, constraints и checksums пакетов. Его коммитят для воспроизводимого init. Версии модулей задаются отдельно: registry version constraint или неизменяемый Git ref. Для удалённых модулей lock file не обеспечивает аналогичной фиксации. Обновления providers проводить отдельным review и проверять планы.",
    "follow_up": "Как подготовить lock для Linux amd64 и arm64? Что делает init -upgrade?",
