    "answer": "Подготовить новый backend, остановить параллельные операции и сделать защищённую копию state. terraform init -migrate-state выполняет миграцию существующего состояния при смене backend с подтверждениями по необходимости. -reconfigure игнорирует сохранённую локальную backend конфигурацию и не выполняет автоматическую миграцию. После перехода проверить выбранный backend, ресурсы и отсутствие неожиданного плана.",
