    "answer": "Lineage идентифицирует историю конкретного state, serial отражает последовательность снимков. Terraform использует эти данные при проверках совместимости записи state, чтобы не перезаписать чужую историю или более новое состояние устаревшим. Они не доказывают корректность реальных объектов. Восстановление требует остановки writers, сверки инфраструктуры и анализа последующих планов.",
