    "answer": "Terraform не гарантирует атомарную транзакцию всей инфраструктуры. Часть объектов может быть создана, изменена или удалена до ошибки. Сохрани журнал и актуальный state, останови другие операции, проверь реальные объекты и затем построй новый plan. Если объект появился, но не привязан к state, согласуй import. Не откатывай state к старому снимку автоматически: это может потерять привязки успешно созданных объектов.",
