    "answer": "Moved сопоставляет старый адрес state с новым в пределах поддерживаемого рефакторинга. При планировании Terraform распознаёт существующий объект по прежнему адресу и переносит привязку, а не считает его автоматически удалённым и новым. Изменения собственных атрибутов всё равно могут потребовать replacement. Moved полезен для перехода к for_each и перемещения ресурсов в модули.",
