    "answer": "Обычный replacement может удалить старый объект до создания нового. Create_before_destroy меняет порядок на создание новой копии перед удалением прежней, если provider и инфраструктура это позволяют. Уникальные имена, квоты, shared storage, зависимые ресурсы и переключение трафика могут препятствовать одновременному существованию. Сам метааргумент не проверяет готовность приложения или сохранность данных.",
