    "question": "Почему prevent_destroy не является достаточной защитой production database?",
    "answer": "Prevent_destroy отклоняет план уничтожения или replacement, пока соответствующее правило присутствует в конфигурации. Если удалить весь resource block, защита не сохраняется как универсальная политика запрета уничтожения. Она не защищает от ручных API действий и иных инструментов. Нужны отдельные provider-side deletion protection, IAM, review планов и проверенные backup/restore.",
    "follow_up": "Почему изменение immutable аргумента может блокироваться? Как проводить согласованное удаление?",
    "practice": "В изолированном terraform_data проверить блокировку replacement при prevent_destroy, затем рассмотреть план удаления самого блока без применения.",
    "rubric": "Назвать границы правила и многослойную защиту данных.",
    "source": "https://developer.hashicorp.com/terraform/language/meta-arguments/lifecycle"
