    "answer": "Replace_triggered_by задаёт декларативное правило replacement при изменении поддерживаемых ссылок на managed resources или их атрибуты. Для обычного значения можно использовать terraform_data как ресурс-посредник. -replace — явное разовое намерение заменить конкретный instance при планировании. Оба механизма требуют проверки зависимостей и downtime; taint устарел как основной способ запроса replacement.",
