    "answer": "Provisioners исполняют императивные действия, которые Terraform не всегда может моделировать, проверить или откатить. Сбои могут оставить частично настроенный объект, а повторные операции — дублировать побочные эффекты. Предпочтительны provider resources, образ с готовой конфигурацией, cloud-init или отдельный configuration management. Если provisioner неизбежен, нужны идемпотентность, timeout, ограниченные права и проверка результата.",
