    "question": "Чем pipeline, stage и job отличаются в GitLab CI?",
    "answer": "Pipeline — экземпляр исполнения конфигурации для события и ref. Stage задаёт стандартный барьер между группами jobs. Job выполняет команды на подходящем runner. Jobs одного stage могут выполняться параллельно при наличии ресурсов; needs меняет граф зависимостей.",
    "follow_up": "Почему job остаётся pending?",
