    "id": "CICD-007",
    "topic": "CI/CD & GitOps",
    "section": "gitlab",
    "level": "senior",
    "question": "Как workflow:rules и job rules предотвращают дублирование push и MR pipelines?",
    "answer": "Workflow rules определяют создание pipeline, job rules — включение job и её свойства. Правила проверяются по порядку до первого совпадения. Учитывают CI_PIPELINE_SOURCE и открытые MR, чтобы не создавать одновременно два pipeline без необходимости. Отдельно проверяют tag, schedule и trigger.",
