    "id": "CICD-008",
    "topic": "CI/CD & GitOps",
    "section": "gitlab",
    "level": "senior",
    "question": "Чем needs отличается от dependencies в GitLab CI?",
    "answer": "Needs задаёт DAG и может разрешить job стартовать до окончания предыдущего stage. Needs:artifacts управляет получением результатов нужных jobs. Dependencies ограничивает скачивание артефактов предшествующих stages, но не является способом построить DAG. Их комбинацию следует избегать согласно документации.",
