    "question": "Почему cache нельзя использовать как единственный источник релизного артефакта?",
    "answer": "Cache ускоряет повторные операции, может отсутствовать или измениться. Artifacts относятся к определённой job и имеют правила скачивания и retention. Выпуск требует проверенного digest, связи с build и доступности в течение rollback window. Кеш не является доказательством происхождения.",
