    "id": "CICD-010",
    "topic": "CI/CD & GitOps",
    "section": "gitlab",
    "level": "senior",
    "question": "Как предотвратить одновременный deploy двух GitLab pipelines в одну среду?",
    "answer": "Resource group сериализует jobs с одним ключом в проекте. Process mode влияет на порядок очереди, но не исключает автоматически устаревшие deployments и операции из других проектов. Нужны проверка revision, environment protection и общий механизм координации внешних writers.",
    "follow_up": "Почему сериализация не гарантирует newest deployment?",
