    "question": "Что означают tags, protected runner и executor в GitLab Runner?",
    "answer": "Tags выбирают подходящий runner; executor определяет способ исполнения, например shell или Docker. Protected runner ограничивает допустимые защищённые refs согласно настройкам GitLab. Tags сами по себе не обеспечивают security boundary. Shell executor особенно требует доверия к коду и изоляции хоста.",
