    "question": "Как передавать секреты в GitLab CI без ложного чувства безопасности от masked variables?",
    "answer": "Использовать ограниченный scope, protected variables, короткоживущую identity и доверенные runners. Masked скрывает некоторые отображения значения в trace, но код с доступом к нему способен раскрыть его. File variables дают путь к временному файлу для подходящих инструментов. Не включать секреты в artifacts и cache.",
