    "question": "Чем parent-child pipeline отличается от multi-project pipeline?",
    "answer": "Child pipeline работает в контексте того же проекта и позволяет выделить компоненты монорепозитория. Multi-project запускает downstream в другом проекте с его ref и правами. Передача artifacts, переменных и статусов требует явного контракта; latest artifact другого проекта не обязательно относится к нужному запуску.",
