    "answer": "Sh обычно падает при ненулевом exit code; returnStatus позволяет обработать код явно. CatchError может изменить результат и продолжить pipeline. Retry повторяет блок, поэтому внешние операции требуют идемпотентности. Post выполняет предусмотренные действия после стадии или pipeline. Обязательную проверку нельзя случайно преобразовать в success.",
