    "question": "Как связаны workflow, event, job, step и runner в GitHub Actions?",
    "answer": "Workflow описывает автоматизацию для событий, jobs запускаются на runners, steps выполняются последовательно в контексте job. Независимые jobs могут идти параллельно; needs задаёт зависимости. Передача файлов между jobs требует artifacts или другого явного механизма.",
    "follow_up": "Что происходит с workspace между jobs?",
    "practice": "Разобрать YAML двух jobs с needs на учебном примере.",
    "rubric": "Различать orchestration, исполнение и передачу данных.",
    "source": "https://docs.github.com/en/actions/reference/workflows-and-actions/workflow-syntax"
