    "question": "Как OIDC позволяет отказаться от постоянного cloud key в GitHub Actions?",
    "answer": "Job с id-token: write может запросить OIDC identity token. Внешний сервис проверяет issuer, audience, subject и другие claims и выдаёт временные credentials в рамках trust policy. Само разрешение id-token не даёт прав на ресурсы. GITHUB_TOKEN permissions настраиваются отдельно; доверие ограничивают repo, ref и environment.",
