    "question": "Чем reusable workflow отличается от composite action?",
    "answer": "Reusable workflow вызывается на уровне job и может описывать несколько jobs, runners и зависимости. Composite action объединяет шаги в одном action, выполняемом внутри job вызывающего workflow. У них различаются интерфейсы inputs, outputs и secrets. Фиксировать доверенную версию и учитывать переданные permissions.",
    "follow_up": "Когда нужен reusable workflow вместо набора общих steps?",
