    "question": "Как избежать ложного успеха matrix jobs при использовании continue-on-error и fail-fast?",
    "answer": "Matrix создаёт несколько jobs по комбинациям параметров. Fail-fast определяет отмену других matrix jobs при ошибке, а continue-on-error позволяет отдельному варианту не блокировать общий результат. Экспериментальные варианты можно сделать необязательными, но обязательная compatibility matrix должна явно влиять на gate. Проверять итоговые статусы, а не только наличие отчётов.",
