    "question": "Как разделить CI и CD в pull-based GitOps архитектуре?",
    "answer": "CI проверяет исходники, собирает образ, публикует его по digest и предлагает изменение конфигурации целевой среды. После review изменение попадает в доверенный источник desired state. CD-agent внутри допустимой границы получает конфигурацию и применяет её. CI не требуется прямой кластерный admin доступ; status синхронизации и здоровье сервиса контролируются отдельно.",
