    "question": "Чем Synced отличается от Healthy в Argo CD?",
    "answer": "Sync status отражает соответствие наблюдаемых управляемых ресурсов желаемому состоянию. Health status оценивает состояние ресурсов по поддерживаемым проверкам. Ресурс может быть Synced, но Degraded из-за плохой readiness или runtime ошибки; Healthy может сопровождаться OutOfSync. Ни один статус не заменяет пользовательский SLI.",
