    "question": "Как отличаются automated sync, selfHeal, prune и allowEmpty в Argo CD?",
    "answer": "Автосинхронизация применяет изменения desired state согласно sync policy. SelfHeal позволяет корректировать изменения live state без нового Git commit. Prune разрешает удалять управляемые ресурсы, отсутствующие в desired state. AllowEmpty снимает специальную защиту от пустого набора ресурсов при соответствующей автоматической очистке. Настройки опасно включать одновременно без проверки scope.",
