    "question": "Как выполнить rollback в GitOps, чтобы контроллер не вернул ошибочную версию?",
    "answer": "Изменить источник желаемого состояния: revert ошибочного конфигурационного commit или новый проверенный commit с предыдущим digest. Дождаться sync и проверить runtime SLI. Ручной rollback Deployment без изменения Git может быть отменён self-heal. Временное отключение reconciliation допустимо только как согласованный emergency шаг с обязательным восстановлением.",
