    "question": "Чем blue-green, rolling update и canary отличаются по управлению трафиком?",
    "answer": "Rolling update постепенно заменяет реплики. Blue-green подготавливает новую версию рядом со старой и переключает маршрут после проверки. Canary постепенно подвергает часть трафика новой версии. Blue-green требует дополнительной ёмкости, canary требует наблюдаемости по версиям и управляемого продвижения. Все стратегии требуют совместимости данных.",
