    "answer": "Если release artifact удалён раньше rollback window, восстановление потребует пересборки или окажется невозможным. Для production сохраняют неизменяемые версии, подписи и метаданные с политикой retention, репликацией и контролем доступа. Временные test artifacts могут иметь меньший срок. Проверять возможность реально скачать и применить предыдущий релиз.",
