    "answer": "Свежая среда ограничивает сохранение файлов, процессов и credentials между jobs. Общий shell runner исполняет код на хосте с правами пользователя runner и способен оставить состояние для следующего запуска. Ephemeral VM или контейнер не является абсолютной защитой: привилегированный режим, общий Docker socket и доступ к внутренней сети могут разрушить изоляцию. Разделять trust domains и credentials.",
