    "answer": "Недоверенная сборка может записать вредоносный результат в cache, который затем использует доверенная job. Разделять ключи и хранилища по trust domain, проверять lock files и контрольные суммы зависимостей, не брать исполняемые release artifacts из общего кеша. Для привилегированных jobs использовать только проверенные входы и учитывать platform-specific cache scope.",
