    "answer": "По средней нагрузке 120 × 4/60 = 8 одновременно занятых executors при устойчивом потоке. При целевой средней загрузке 70% требуется ceil(8/0,7)=12 slots. Это ориентир, а не гарантия очереди: учитывать bursts, длительности, разные классы jobs, ограничения памяти и CPU, provisioning latency и измеренный p95 queue time.",
