    "answer": "USER меняет пользователя приложения в контейнере. userns-remap отображает UID на непривилегированные UID хоста, но daemon остаётся rootful. Rootless запускает daemon и контейнеры без host root через user namespaces. Ограничения сети, storage и cgroups зависят от окружения.",
