    "answer": "Live-restore может сохранить запущенные Linux-контейнеры при недоступности daemon в поддерживаемой конфигурации. Управление ограничено; есть ограничения совместимости обновлений и риск блокировки логов при заполнении буфера. Он не спасает от отказа ядра, питания или хранилища.",
