    "answer": "Измерить CPU, память, диск, IOPS, сеть, задать лимиты и запас на пики. Разделить критичные сервисы и домены отказа, обеспечить наблюдаемость, обновления, backup/restore и ownership. Compose сам не планирует workloads по хостам; при требованиях failover оценить оркестратор и стоимость миграции.",
