    "answer": "Control node разбирает inventory и playbook, выбирает hosts и connection plugin, подготавливает аргументы и вызывает action/module. Типичные POSIX-модули выполняются с Python на целевом хосте через SSH, Windows-модули используют PowerShell. Некоторые операции выполняются на контроллере; постоянный агент обычно не нужен.",
