    "id": "ANS-002",
    "topic": "Ansible",
    "section": "fundamentals",
    "level": "middle",
    "question": "Что такое идемпотентность Ansible и как доказать её практически?",
    "answer": "При одинаковых входах повторное применение уже достигнутого желаемого состояния не должно создавать лишних изменений. Проверяют реальные эффекты и второй запуск с changed=0 для задач согласования. Намеренные операции вроде перезапуска или чтения времени требуют отдельного контракта; changed_when: false сам по себе идемпотентность не создаёт.",
    "follow_up": "Почему два запуска без ошибок недостаточны?",
    "practice": "На временном каталоге проверить содержимое, права и второй запуск роли.",
    "rubric": "Различать reported changed и реальные side effects.",
