    "answer": "command запускает программу без полноценной shell-интерпретации операторов; shell выполняет команду через оболочку, поэтому нужны корректное экранирование и проверка входов. raw отправляет низкоуровневую команду без обычной Python-модульной обвязки, полезен для bootstrap. Предпочитать специализированный модуль или command с argv.",
