    "answer": "Facts собираются модулем setup и описывают состояние хоста на момент опроса. Кеш ускоряет последующие запуски, но может устареть. Для решений о релизе проверять критические данные непосредственно перед действием, задавать TTL, область хранения и права доступа. При gather_facts: false нужные факты собирают явно.",
