    "answer": "WAL обеспечивает восстановление недавних принятых samples, head содержит активные данные, затем создаются блоки с индексом и chunks. Compaction объединяет блоки и управляет их жизненным циклом. Локальная TSDB не является распределённым durable storage; резервирование требует отдельного дизайна.",
