    "answer": "Правило вычисляет состояние alert instance, notification policy маршрутизирует уведомления по labels и задаёт группировку и интервалы. Contact point определяет канал доставки. Проверять routing отдельно от expression, не создавать копии правила только ради разных каналов.",
