    "answer": "Определить Git как источник истины для provisioned объектов, использовать стабильные UID, ревью, отдельные окружения и проверку deployment. Ручные изменения provisioned объектов могут быть запрещены или перезаписаны в зависимости от механизма. Процедура исключений должна вернуть изменения в Git и проверить фактическое состояние.",
