    "question": "Как partition key влияет на порядок сообщений?",
    "answer": "Producer обычно направляет одинаковый key в одну partition при неизменном partitioner и числе partitions. Kafka гарантирует порядок журнала в пределах partition, не всего topic. При увеличении числа partitions mapping может измениться.",
