    "question": "Что такое ISR и почему replication factor не равен числу актуальных реплик?",
    "answer": "Replication factor задаёт число назначенных реплик, ISR — множество синхронизированных с leader по критериям Kafka. Отстающая replica может покинуть ISR. Состояние ISR влияет на допустимость подтверждённой записи и выбор leader; проверять under-replicated partitions.",
