    "id": "KAFKA-004",
    "topic": "Kafka",
    "section": "architecture",
    "level": "senior",
    "question": "Как взаимодействуют acks=all, min.insync.replicas и RF=3?",
    "answer": "При acks=all подтверждения нужны от текущих ISR, а min.insync.replicas задаёт минимальный допустимый размер ISR для записи. RF=3 и min ISR=2 позволяют потерять одну replica при двух актуальных; при ISR=1 подтверждённая запись блокируется. Это компромисс durability и write availability.",
