    "level": "senior",
    "question": "Что такое high watermark и чем он отличается от log end offset?",
    "answer": "LEO — следующая позиция в локальном журнале replica; high watermark отражает границу реплицированных записей, доступных обычному чтению. Для read_committed дополнительно ограничивает last stable offset. Разрыв границ помогает диагностировать replication lag или незавершённые транзакции.",
