    "question": "Как KRaft quorum влияет на отказоустойчивость Kafka?",
    "answer": "Controller quorum хранит и согласует метаданные через Raft; для прогресса нужно большинство голосующих controllers. Три controller выдерживают потерю одного, пять — двух при независимых отказах. Broker replication отвечает за данные отдельно. Потеря quorum ограничивает изменения метаданных и восстановление, даже если часть трафика ещё обслуживается.",
    "follow_up": "Почему три brokers не заменяют controller quorum?",
