    "answer": "0 не ждёт ответа broker, 1 подтверждает запись leader, all ждёт текущие ISR при допустимом min ISR. Чем слабее подтверждение, тем выше риск неопределённости или потери при отказе. Latency зависит от replication, сети и batching; аcks не заменяет проверку ошибок.",
