    "answer": "Producer использует идентификатор и sequence numbers для подавления повторов при поддерживаемых retries. Нужны совместимые acks=all, retries и max.in.flight<=5. Это не дедуплицирует логически одинаковые события от разных вызовов send или внешние side effects. Проверять версию клиента.",
