    "answer": "Producer группирует записи по partition; linger допускает ожидание наполнения batch, batch.size задаёт ориентир размера, compression сокращает трафик и хранение за CPU. Настройки подбирают по реальной нагрузке и p99; latency при насыщении зависит также от очередей и broker.",
