    "answer": "Position — следующая позиция чтения в текущем процессе, committed offset — сохранённая точка возобновления группы. При restart или rebalance чтение может начаться с committed offset, а обработанные после него записи повторятся. Commit должен соответствовать завершённой обработке.",
