    "answer": "Политика применяется, когда сохранённого offset нет или он больше недоступен, например из-за retention. earliest начинает с доступного начала, latest — с конца, none сигнализирует об ошибке; дополнительные варианты зависят от версии. Она не переопределяет валидный commit при каждом старте.",
