    "id": "PG-004",
    "topic": "PostgreSQL & Patroni",
    "section": "internals",
    "level": "senior",
    "question": "Как shared_buffers и OS page cache взаимодействуют?",
    "answer": "PostgreSQL использует собственный buffer cache, а обычный файловый I/O также задействует кеш ОС. Увеличение shared_buffers не гарантирует ускорения и уменьшает память для других задач. Сравнивать рабочий набор, hit ratio, физический I/O и memory pressure; cache hit не равен нулевой latency.",
