    "id": "PG-005",
    "topic": "PostgreSQL & Patroni",
    "section": "internals",
    "level": "senior",
    "question": "Почему work_mem нельзя умножать только на число подключений?",
    "answer": "work_mem используется отдельными операциями sort/hash и может выделяться несколько раз в одном запросе, включая parallel workers. Hash operations учитывают hash_mem_multiplier. Оценивать активные запросы, concurrency и фактический план; завышение глобального значения может вызвать OOM.",
