    "id": "PG-006",
    "topic": "PostgreSQL & Patroni",
    "section": "transactions",
    "level": "middle",
    "question": "Чем READ COMMITTED отличается от REPEATABLE READ в PostgreSQL?",
    "answer": "В READ COMMITTED новый statement получает snapshot актуальных committed данных, а REPEATABLE READ использует стабильный snapshot транзакции и может завершиться ошибкой при конкурентном update. SERIALIZABLE дополнительно предотвращает serialization anomalies через обнаружение опасных зависимостей и требует retry.",
