    "question": "Чем deadlock отличается от длительного lock wait?",
    "answer": "Deadlock образует цикл ожидания; PostgreSQL обнаруживает его и отменяет одну транзакцию. Обычная блокировка может закончиться после commit другого участника либо timeout. Сокращать транзакции, брать locks в согласованном порядке и обрабатывать retry целой транзакции при нужном SQLSTATE.",
