    "answer": "Старый snapshot или xmin может удерживать версии строк, необходимые для видимости. Vacuum не сможет удалить ещё потенциально видимые tuples, растут bloat и объём I/O. Проверять backend_xmin, xact_start, locks и replication feedback, устранять причину в приложении.",
