    "question": "Чем VACUUM, ANALYZE и VACUUM FULL различаются?",
    "answer": "VACUUM освобождает место для повторного использования и выполняет задачи visibility/freezing; ANALYZE обновляет статистику планировщика. VACUUM FULL переписывает таблицу, может вернуть место ОС, требует дополнительного диска и ACCESS EXCLUSIVE lock. Не применять FULL как штатную ежедневную процедуру.",
