    "answer": "XID имеют ограниченное пространство и циклически переиспользуются; старые версии нужно замораживать, чтобы не нарушить видимость. Autovacuum выполняет anti-wraparound vacuum, даже при некоторых отключённых обычных настройках. Контролировать age(datfrozenxid), relfrozenxid, долгие транзакции и прогресс vacuum.",
