    "question": "Как измерить RTO восстановления базы 2 TB при effective restore 200 MB/s?",
    "answer": "Только копирование занимает 2 000 000 MB / 200 MB/s = 10000 секунд, около 2 ч 47 мин. Добавить provisioning, WAL replay, validation, переключение клиентов и запас; throughput измерять end-to-end. Если RTO меньше, нужны другие механизмы standby/backup и испытания.",
