    "question": "Что делают Patroni, PostgreSQL и DCS в HA-кластере?",
    "answer": "PostgreSQL хранит и реплицирует данные, Patroni управляет жизненным циклом и выбором primary, DCS хранит согласованное состояние и leader lock. DCS не содержит саму базу. Клиенты используют отдельный механизм routing и reconnect, проверяющий роль экземпляра.",
