    "id": "PG-029",
    "topic": "PostgreSQL & Patroni",
    "section": "patroni",
    "level": "senior",
    "question": "Как ttl, loop_wait и retry_timeout влияют на failover Patroni?",
    "answer": "ttl задаёт срок действия leader lock, loop_wait — период HA loop, retry_timeout — ожидания повторных операций с DCS/Postgres. Patroni требует согласованности параметров, включая loop_wait + 2*retry_timeout <= ttl. Слишком малые значения усиливают чувствительность к временным задержкам; фактический RTO включает promotion и routing.",
    "follow_up": "Почему ttl не равен полному RTO?",
