    "section": "patroni",
    "level": "senior",
    "question": "Что произойдёт при недоступности DCS и работающем primary?",
    "answer": "Без специальных условий Patroni защищает от split brain и может демотировать primary при невозможности продлить lock. DCS failsafe mode позволяет продолжить работу при выполнении условий связи с известными участниками через REST API; это не универсальная замена quorum. Проверять конкретную версию и сценарий partition.",
