    "answer": "Synchronous mode координирует выбор standby и допустимых кандидатов promotion; без подходящего standby обычный режим может временно разрешить запись без sync replication. Strict сохраняет требование sync и может блокировать writes. Режим не отменяет ограничения аварийных сценариев и ручных операций.",
