    "question": "Зачем Patroni watchdog, если уже есть leader lock в DCS?",
    "answer": "Watchdog добавляет fencing: если узел не может своевременно подтвердить безопасное состояние, watchdog может перезагрузить его, ограничивая риск старого writer. В required mode отсутствие рабочего watchdog препятствует лидерству. Проверять реальную поддержку устройства и timing; не считать watchdog единственной защитой.",
