    "answer": "После divergence timelines pg_rewind синхронизирует target с новым source при выполнении требований, включая checksums либо wal_log_hints и нужный WAL. Старый primary должен быть безопасно остановлен и исключён из writers; затем проверяют recovery и роль. Если rewind невозможен, используют новый base backup/reinit.",
