    "answer": "Issuer подтверждает происхождение token, audience ограничивает целевого получателя, subject и другие claims определяют разрешённую identity. Проверять signature, expiration и нужный context репозитория/окружения. Широкая wildcard policy может дать чужому workflow доступ к production.",
