    "answer": "Environment обычно фиксируется при старте процесса и требует его обновления. Secret volume обычно обновляется с задержкой, но subPath mount не получает такие обновления. Приложение должно перечитать файл; проверять тайминг и rollout, не считать обновление объекта доказательством rotation.",
