    "question": "Что такое stateless service и где всё равно хранится состояние?",
    "answer": "Stateless instance не требует уникального локального состояния для обработки следующего запроса. Сессии, durable данные и координация могут храниться во внешнем сервисе или переносимом токене. Это облегчает замену instances, но переносит reliability требования на dependencies.",
