    "id": "SYS-016",
    "topic": "System Design & Platform Engineering",
    "section": "distributed",
    "level": "senior",
    "question": "Почему quorum N=5 требует минимум три голоса и что даёт пересечение большинств?",
    "answer": "Любые два множества большинства из пяти пересекаются, что помогает согласованно выбирать решения при корректном consensus protocol. Три голоса переживают два независимых отказа. Пересечение само по себе не заменяет правила term, log и fencing; размещение определяет реальные failure domains.",
    "follow_up": "Что произойдёт при partition 2+2+1?",
