    "id": "SYS-017",
    "topic": "System Design & Platform Engineering",
    "section": "distributed",
    "level": "senior",
    "question": "Чем lease отличается от fencing token при распределённой блокировке?",
    "answer": "Lease ограничивает срок владения, но старый владелец после паузы может продолжить действие, не зная об истечении. Fencing token монотонно упорядочивает поколения владельцев; защищаемый ресурс должен отклонять старые токены. Без проверки на ресурсе token не защищает side effects.",
    "follow_up": "Почему TTL lock не защищает от долгой GC паузы?",
