    "answer": "Клиент передаёт стабильный idempotency key, сервер атомарно связывает его с результатом и параметрами операции. Повтор возвращает согласованный результат или ожидает завершения; несовместимый payload отклоняется. Retention ключа должен покрывать retry horizon. Внешние side effects требуют собственной защиты.",
