    "answer": "RPC подходит при необходимости непосредственного результата, но связывает latency и availability зависимостей. Очередь сглаживает нагрузку и допускает отложенную обработку, добавляя lag, повторы, ordering и recovery. Определить пользовательский deadline, durability и допустимое поведение при backlog.",
