    "answer": "Golden path — поддерживаемый рекомендуемый способ выполнения типовой задачи, с безопасными defaults и быстрым результатом. Исследовать потребности команд, уменьшить friction, документировать escape hatch и измерять adoption и удовлетворённость. Обязательные controls отделять от необязательных решений реализации.",
